functions.workload_status_path:
def workload_status_path(profile):
    profile = Path(profile)
    return profile.with_name(profile.name + '.workload-status.json')

functions.write_trial_json:
def write_trial_json(path: Path, document: dict) -> None:
    """Write strict ASCII JSON in insertion order with one final newline."""
    path.write_text(json.dumps(document, indent=2, allow_nan=False) + "\n")

functions.event:
def event(name, **data):
    with lock, (out / 'events.jsonl').open('a') as f:
        f.write(json.dumps({'epoch': time.time(), 'event': name, **data}) + '\n')
